// Manjesh Grand Line - the Code Preview destination's web side.
//
// Hand-written entry point for the bundle `native/Scripts/build-monaco-web.sh`
// produces (see ../README.md). It mounts one full-page Monaco editor and
// exposes exactly one global, `window.GrandLineCodePreview`, as the bridge the
// native side drives with `evaluateJavaScript`. Nothing here reaches the
// network: the whole editor, its codicon font and every language definition
// are inlined into the one committed bundle, and index.html carries a
// Content-Security-Policy that makes that structural rather than a claim.
//
// The same two conventions as the Whiteboard's own entry point, and for the
// same reasons:
//
//   1. **Every entry point answers.** Each bridge call posts exactly one
//      `{ type: "reply", callID, ok, ... }` back to Swift, so the native side
//      never has to guess whether an `evaluateJavaScript` that returned
//      `undefined` actually did anything.
//   2. **No always-on animation or polling.** Nothing here runs on a timer
//      except the one debounce below, which is armed by a real edit and
//      disarms itself. Monaco's caret blink is a CSS animation, and
//      `suspend()` stops it along with everything else.
//
// ## What this page is, and what it deliberately is not
//
// It is the editor surface and nothing else. The tab bar, the toolbar, the
// language picker and the status line are **real AppKit**, built out of this
// app's own design system (`TabChipView`, `HelmPageToolbar`,
// `HelmPopUpButton`) by `CodePreviewController`.
//
// That is the opposite call from the Whiteboard, on purpose, and the reason is
// what each library actually ships: Excalidraw ships a complete, mature
// toolbar, so re-drawing it natively would be duplication. Monaco ships **no**
// tab bar and **no** status bar at all - those are VS Code *workbench*
// features, not `monaco-editor` - so they have to be built either way, and
// building them in HTML would put a second, un-themed visual language inside
// an app whose own self-tests ban a stock button bezel.
//
// It is also not an IDE. `monaco-editor`'s `vs/language/*` packages (the
// TypeScript/JSON/CSS/HTML *services* - validation, IntelliSense, hovers) are
// deliberately not imported. What is imported is `editor.all.js` (the editor's
// own contributions: find, folding, bracket matching, multi-cursor, the
// context menu) plus a hand-picked set of `basic-languages`, which are pure
// Monarch tokenizers - syntax highlighting, no language server, no completion
// beyond Monaco's own word-based one.
//
// ## The worker
//
// Monaco's `EditorWorkerService` is needed even with no language service
// registered: link detection and the unicode highlighter both run through it
// on ordinary text. Left without a `MonacoEnvironment`, Monaco throws the
// first time it wants one.
//
// The worker's own bundle is inlined into *this* file as source text at build
// time and started from a Blob URL. A sibling `editor.worker.js` file would
// have been simpler, but this page is loaded from a `file://` origin, where
// starting a worker from a relative path is not portable (and `fetch()`ing it
// to make a Blob is blocked outright). A Blob URL inherits this document's
// origin, which is why `worker-src 'self' blob:` in the CSP is what covers it.
import "monaco-editor/esm/vs/editor/editor.all.js";
import * as monaco from "monaco-editor/esm/vs/editor/editor.api.js";

// The captain's own day-to-day set (the task's named list) plus the DevOps
// formats this app already deals in everywhere else - a cockpit that can read
// a Dockerfile, a Terraform file and a SQL query is worth the ~10KB each of
// these costs. Every one is a `basic-languages` Monarch tokenizer: highlight
// only, no service, no worker of its own.
import "monaco-editor/esm/vs/basic-languages/swift/swift.contribution.js";
import "monaco-editor/esm/vs/basic-languages/yaml/yaml.contribution.js";
import "monaco-editor/esm/vs/basic-languages/python/python.contribution.js";
import "monaco-editor/esm/vs/basic-languages/go/go.contribution.js";
import "monaco-editor/esm/vs/basic-languages/rust/rust.contribution.js";
import "monaco-editor/esm/vs/basic-languages/shell/shell.contribution.js";
import "monaco-editor/esm/vs/basic-languages/javascript/javascript.contribution.js";
import "monaco-editor/esm/vs/basic-languages/typescript/typescript.contribution.js";
import "monaco-editor/esm/vs/basic-languages/dockerfile/dockerfile.contribution.js";
import "monaco-editor/esm/vs/basic-languages/sql/sql.contribution.js";
import "monaco-editor/esm/vs/basic-languages/hcl/hcl.contribution.js";
import "monaco-editor/esm/vs/basic-languages/markdown/markdown.contribution.js";
import "monaco-editor/esm/vs/basic-languages/xml/xml.contribution.js";
import "monaco-editor/esm/vs/basic-languages/ini/ini.contribution.js";

// Generated by the build script - the editor worker's own bundle, as text.
// See "The worker" above.
import editorWorkerSource from "./editor.worker.bundle.txt";

// --- Native bridge plumbing -----------------------------------------------

const post = (payload) => {
  try {
    window.webkit.messageHandlers.grandlineCodePreview.postMessage(payload);
  } catch (err) {
    // No native host (e.g. the page opened in a plain browser for debugging).
    // Never throw from a bridge call just because nobody is listening.
    if (window.console) console.warn("code preview: no native host", err);
  }
};

const reply = (callID, body) => {
  if (callID === undefined || callID === null) return;
  post({ type: "reply", callID, ...body });
};

// --- The worker -----------------------------------------------------------

let workerURL = null;
self.MonacoEnvironment = {
  getWorker() {
    if (!workerURL) {
      workerURL = URL.createObjectURL(
        new Blob([editorWorkerSource], { type: "text/javascript" })
      );
    }
    return new Worker(workerURL);
  },
};

// --- JSON -----------------------------------------------------------------
//
// `monaco-editor` has no `basic-languages/json`: JSON is covered by its full
// `vs/language/json` *service* (schema validation, completion, a second
// worker), which is exactly the IntelliSense machinery this panel is not
// supposed to carry. So JSON gets a small Monarch tokenizer of its own here.
//
// Deliberately a tokenizer and not a parser: it colours keys, strings, numbers
// and literals, and says nothing about whether the document is valid. A
// "paste and see it rendered properly" panel wants exactly that - a
// half-pasted fragment must still highlight rather than turn into a wall of
// error squiggles.
monaco.languages.register({
  id: "json",
  extensions: [".json", ".jsonc"],
  aliases: ["JSON", "json"],
  mimetypes: ["application/json"],
});
monaco.languages.setLanguageConfiguration("json", {
  comments: { lineComment: "//", blockComment: ["/*", "*/"] },
  brackets: [
    ["{", "}"],
    ["[", "]"],
  ],
  autoClosingPairs: [
    { open: "{", close: "}" },
    { open: "[", close: "]" },
    { open: '"', close: '"', notIn: ["string"] },
  ],
});
monaco.languages.setMonarchTokensProvider("json", {
  defaultToken: "",
  tokenPostfix: ".json",
  tokenizer: {
    root: [
      // A string immediately followed by a colon is a key, whatever the
      // nesting - which is the one distinction that makes JSON readable at a
      // glance and the reason this is not just "highlight it as YAML".
      [/"(?:[^"\\]|\\.)*"(?=\s*:)/, "type"],
      [/"(?:[^"\\]|\\.)*"/, "string"],
      [/"/, "string.invalid"],
      [/-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?/, "number"],
      [/\b(?:true|false|null)\b/, "keyword"],
      [/[{}[\]]/, "@brackets"],
      [/[,:]/, "delimiter"],
      // JSONC: not valid strict JSON, but pasting a `tsconfig.json` or a
      // `.vscode/settings.json` is exactly what this panel is for.
      [/\/\/.*$/, "comment"],
      [/\/\*/, "comment", "@comment"],
      [/[ \t\r\n]+/, ""],
    ],
    comment: [
      [/[^/*]+/, "comment"],
      [/\*\//, "comment", "@pop"],
      [/[/*]/, "comment"],
    ],
  },
});

// --- Theme ----------------------------------------------------------------
//
// Monaco's own `vs`/`vs-dark` are ignored: this panel has to read as part of
// the app, so the native side hands over colours resolved from the *active
// Helm theme* and this builds a Monaco theme out of them. That is the same
// call `WhiteboardController.pushTheme` makes for Excalidraw's light/dark, one
// level more detailed because a code editor has real token colours to place.
//
// `base` still matters even with every colour supplied: it is what Monaco
// falls back to for the handful of UI colours not named here.
const THEME_ID = "grandline";

function applyTheme(t) {
  const dark = t.mode === "dark";
  monaco.editor.defineTheme(THEME_ID, {
    base: dark ? "vs-dark" : "vs",
    inherit: true,
    rules: [
      { token: "", foreground: strip(t.ink) },
      { token: "comment", foreground: strip(t.comment), fontStyle: "italic" },
      { token: "keyword", foreground: strip(t.keyword) },
      { token: "keyword.json", foreground: strip(t.constant) },
      { token: "string", foreground: strip(t.string) },
      { token: "string.escape", foreground: strip(t.constant) },
      { token: "number", foreground: strip(t.constant) },
      { token: "regexp", foreground: strip(t.string) },
      { token: "operator", foreground: strip(t.operator) },
      { token: "delimiter", foreground: strip(t.operator) },
      { token: "type", foreground: strip(t.type) },
      { token: "type.identifier", foreground: strip(t.type) },
      { token: "identifier", foreground: strip(t.ink) },
      { token: "attribute.name", foreground: strip(t.type) },
      { token: "attribute.value", foreground: strip(t.string) },
      { token: "tag", foreground: strip(t.keyword) },
      { token: "metatag", foreground: strip(t.keyword) },
      { token: "variable", foreground: strip(t.ink) },
      { token: "variable.predefined", foreground: strip(t.constant) },
      { token: "constant", foreground: strip(t.constant) },
      { token: "predefined", foreground: strip(t.function) },
      { token: "function", foreground: strip(t.function) },
      { token: "annotation", foreground: strip(t.function) },
      { token: "invalid", foreground: strip(t.invalid) },
      { token: "string.invalid", foreground: strip(t.invalid) },
    ],
    colors: {
      "editor.background": t.background,
      "editor.foreground": t.ink,
      "editorLineNumber.foreground": t.lineNumber,
      "editorLineNumber.activeForeground": t.ink,
      "editorCursor.foreground": t.accent,
      "editor.selectionBackground": t.selection,
      "editor.inactiveSelectionBackground": t.selectionInactive,
      "editor.lineHighlightBackground": t.currentLine,
      "editorIndentGuide.background1": t.line,
      "editorIndentGuide.activeBackground1": t.lineNumber,
      "editorWhitespace.foreground": t.line,
      "editorBracketMatch.background": t.selectionInactive,
      "editorBracketMatch.border": t.accent,
      "editorWidget.background": t.chrome,
      "editorWidget.foreground": t.ink,
      "editorWidget.border": t.line,
      "editorSuggestWidget.background": t.chrome,
      "editorSuggestWidget.border": t.line,
      "editorSuggestWidget.selectedBackground": t.selectionInactive,
      "input.background": t.background,
      "input.foreground": t.ink,
      "input.border": t.line,
      "focusBorder": t.accent,
      "scrollbarSlider.background": t.scrollbar,
      "scrollbarSlider.hoverBackground": t.scrollbarHover,
      "scrollbarSlider.activeBackground": t.scrollbarHover,
      "minimap.background": t.background,
    },
  });
  monaco.editor.setTheme(THEME_ID);
  document.documentElement.dataset.theme = dark ? "dark" : "light";
}

/// Monaco's token `rules` want a bare hex with no leading `#`, while its
/// `colors` map wants the `#`. One conversion in one place rather than two
/// shapes of the same value crossing the bridge.
const strip = (hex) => String(hex || "").replace(/^#/, "");

// --- The editor -----------------------------------------------------------

/// Every open snippet's model, by the id the native side assigned it. Monaco
/// keeps a model's full undo history and view state, which is what makes
/// switching tabs feel like switching tabs rather than reloading a file.
const models = new Map();
/// Scroll position, cursor and folding per snippet, saved on the way out of a
/// tab and restored on the way back in.
const viewStates = new Map();

let editor = null;
let currentID = null;
/// Set while the native side is installing content, so the change that causes
/// does not bounce straight back to it as if the captain had typed it.
let applyingRemoteEdit = false;

const container = document.getElementById("editor");

editor = monaco.editor.create(container, {
  value: "",
  language: "plaintext",
  automaticLayout: true,
  // A paste-and-view panel, so: readable defaults, and none of the
  // project-awareness Monaco would happily turn on.
  minimap: { enabled: false },
  scrollBeyondLastLine: false,
  renderLineHighlight: "line",
  roundedSelection: false,
  smoothScrolling: true,
  cursorBlinking: "smooth",
  fontLigatures: false,
  tabSize: 2,
  // Word-based suggestions are Monaco's own "other words in this file"
  // completer. It is not IntelliSense, but it is still an autocomplete popup
  // in a panel whose whole job is reading - and the task's bar is explicit
  // that no completion is wired here.
  wordBasedSuggestions: "off",
  quickSuggestions: false,
  suggestOnTriggerCharacters: false,
  parameterHints: { enabled: false },
  // Nothing in this app opens a URL out of the editor, and a clickable link
  // inside pasted code is a navigation this page must never perform.
  links: false,
  contextmenu: true,
  scrollbar: { useShadows: false, verticalScrollbarSize: 10, horizontalScrollbarSize: 10 },
});

// --- Change reporting -----------------------------------------------------
//
// One debounce, armed by a real edit. The native side coalesces again on its
// own side before committing to git, so this only has to be short enough that
// a pause in typing reaches disk promptly and long enough that a burst of
// keystrokes is one message rather than forty.
const CHANGE_DEBOUNCE_MS = 500;
let changeTimer = null;
let pendingChangeID = null;

function postPendingChange() {
  if (changeTimer !== null) {
    clearTimeout(changeTimer);
    changeTimer = null;
  }
  const id = pendingChangeID;
  pendingChangeID = null;
  if (id === null) return;
  const model = models.get(id);
  if (!model) return;
  post({ type: "change", id, content: model.getValue() });
}

editor.onDidChangeModelContent(() => {
  if (applyingRemoteEdit || currentID === null) return;
  pendingChangeID = currentID;
  if (changeTimer !== null) clearTimeout(changeTimer);
  changeTimer = setTimeout(postPendingChange, CHANGE_DEBOUNCE_MS);
});

editor.onDidChangeCursorPosition((event) => {
  const selection = editor.getSelection();
  const model = editor.getModel();
  let selected = 0;
  if (selection && model && !selection.isEmpty()) {
    selected = model.getValueInRange(selection).length;
  }
  post({
    type: "cursor",
    line: event.position.lineNumber,
    column: event.position.column,
    selected,
    lines: model ? model.getLineCount() : 0,
  });
});

// --- The bridge -----------------------------------------------------------

function modelFor(id, language, content) {
  let model = models.get(id);
  if (model) {
    if (typeof content === "string" && content !== model.getValue()) {
      applyingRemoteEdit = true;
      try {
        model.setValue(content);
      } finally {
        applyingRemoteEdit = false;
      }
    }
    if (language) monaco.editor.setModelLanguage(model, language);
    return model;
  }
  model = monaco.editor.createModel(content || "", language || "plaintext");
  models.set(id, model);
  return model;
}

const bridge = {
  /// Creates (or updates) a snippet's model and, unless told otherwise, shows
  /// it. The native side owns ids, names and the tab order; this only ever
  /// holds text and a language.
  openSnippet(callID, payload) {
    try {
      const id = String(payload.id);
      const model = modelFor(id, payload.language, payload.content);
      if (payload.select !== false) selectModel(id);
      reply(callID, { ok: true, id, lines: model.getLineCount() });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  selectSnippet(callID, payload) {
    try {
      const id = String(payload.id);
      if (!models.has(id)) throw new Error("no such snippet");
      selectModel(id);
      reply(callID, { ok: true, id });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  /// Disposes a snippet's model. A model kept after its tab is gone is a real
  /// leak - Monaco holds the full text plus its undo stack - so this is not
  /// merely bookkeeping.
  closeSnippet(callID, payload) {
    try {
      const id = String(payload.id);
      // Whatever is still pending for this snippet must be flushed before its
      // model is disposed, or the captain's last keystrokes are lost between
      // the debounce firing and the tab closing.
      if (pendingChangeID === id) postPendingChange();
      const model = models.get(id);
      if (model) model.dispose();
      models.delete(id);
      viewStates.delete(id);
      if (currentID === id) currentID = null;
      reply(callID, { ok: true, id, open: models.size });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  setLanguage(callID, payload) {
    try {
      const id = String(payload.id);
      const model = models.get(id);
      if (!model) throw new Error("no such snippet");
      monaco.editor.setModelLanguage(model, payload.language || "plaintext");
      reply(callID, { ok: true, id, language: model.getLanguageId() });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  getContent(callID, payload) {
    try {
      const id = String(payload.id);
      const model = models.get(id);
      if (!model) throw new Error("no such snippet");
      reply(callID, { ok: true, id, content: model.getValue() });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  /// Posts any debounced edit immediately. Called by the native side when the
  /// destination is hidden and when the app is about to quit, so the last few
  /// keystrokes before a navigate-away are never the ones that got lost.
  flush(callID) {
    postPendingChange();
    reply(callID, { ok: true });
  },

  setTheme(callID, payload) {
    try {
      applyTheme(payload.theme || {});
      reply(callID, { ok: true });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  /// Reads back what `applyTheme` actually did to the page, rather than
  /// merely whether the bridge call that requested it succeeded - the two
  /// diverged for real once (`CodePreviewTheme.Key.operatorToken`'s wire-name
  /// mismatch made `monaco.editor.defineTheme` throw on every push, silently,
  /// since the native side sent `setTheme` with no completion handler at the
  /// time). `.monaco-editor-background`'s own computed colour is Monaco's
  /// literal rendered editor surface, not a value this app handed over -
  /// exactly the same "read the tokenizer's own output" standard `tokensAt`
  /// already holds this feature to for highlighting.
  readThemeProbe(callID) {
    const el = document.querySelector(".monaco-editor-background");
    reply(callID, {
      ok: true,
      theme: document.documentElement.dataset.theme || null,
      background: el ? getComputedStyle(el).backgroundColor : null,
    });
  },

  setFontSize(callID, payload) {
    try {
      const size = Number(payload.size);
      if (!Number.isFinite(size) || size <= 0) throw new Error("bad font size");
      editor.updateOptions({ fontSize: size, lineHeight: 0 });
      reply(callID, { ok: true, size });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  setWordWrap(callID, payload) {
    try {
      editor.updateOptions({ wordWrap: payload.on ? "on" : "off" });
      reply(callID, { ok: true, on: !!payload.on });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  focusEditor(callID) {
    editor.focus();
    reply(callID, { ok: true });
  },

  /// Opens Monaco's own find widget - the app's Edit menu routes ⌘F here
  /// while this destination is showing, the same way it routes ⌘F to the
  /// terminal's find bar on Console.
  find(callID) {
    try {
      editor.getAction("actions.find").run();
      reply(callID, { ok: true });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },

  stats(callID) {
    const model = editor.getModel();
    reply(callID, {
      ok: true,
      open: models.size,
      current: currentID,
      lines: model ? model.getLineCount() : 0,
      language: model ? model.getLanguageId() : "plaintext",
      suspended,
    });
  },

  /// Called when the destination is hidden (and again when it is shown).
  ///
  /// WebKit already stops painting and throttles `requestAnimationFrame` for a
  /// `WKWebView` whose NSView is hidden, so this is not what keeps idle cost
  /// at zero. What it adds is the part WebKit cannot know about: Monaco's own
  /// CSS transitions and its blinking caret are stopped outright, the editor
  /// loses focus, and any debounced edit is written out rather than left
  /// waiting on a timer in a page nobody is looking at.
  suspend(callID) {
    suspended = true;
    postPendingChange();
    document.documentElement.classList.add("gl-suspended");
    if (document.activeElement && document.activeElement.blur) {
      document.activeElement.blur();
    }
    stopGatingProbe();
    reply(callID, { ok: true, visibility: document.visibilityState });
  },

  resume(callID) {
    suspended = false;
    document.documentElement.classList.remove("gl-suspended");
    reply(callID, { ok: true, visibility: document.visibilityState });
  },

  // --- Gating probe -------------------------------------------------------
  //
  // Dormant by default and only ever started by an explicit native call, so
  // this file has no always-on loop. Same shape, and the same purpose, as the
  // Whiteboard's: "the hidden destination costs nothing" deserves evidence
  // stronger than an eyeball, and a rAF counter that stops advancing while the
  // view is hidden is WebKit saying it stopped compositing this page.
  startGatingProbe(callID) {
    startGatingProbe();
    reply(callID, { ok: true });
  },

  readGatingProbe(callID) {
    reply(callID, {
      ok: true,
      frames: probeFrames,
      visibility: document.visibilityState,
      suspended,
    });
  },

  /// The rendered token colours at a position, read back out of Monaco's own
  /// tokenizer. This is what lets a self-test assert that highlighting
  /// genuinely happened and is legible against the theme's background, rather
  /// than asserting that a theme object was handed over.
  tokensAt(callID, payload) {
    try {
      const model = editor.getModel();
      if (!model) throw new Error("no model");
      const line = Number(payload.line) || 1;
      const tokens = monaco.editor.tokenize(model.getLineContent(line), model.getLanguageId());
      const flat = (tokens[0] || []).map((t) => ({ offset: t.offset, type: t.type }));
      reply(callID, { ok: true, line, tokens: flat, language: model.getLanguageId() });
    } catch (err) {
      reply(callID, { ok: false, message: describe(err) });
    }
  },
};

function selectModel(id) {
  if (currentID !== null && currentID !== id) {
    // Flush before switching, or a debounce that fires after the switch would
    // read the *new* tab's text and write it into the old tab's file.
    if (pendingChangeID === currentID) postPendingChange();
    const state = editor.saveViewState();
    if (state) viewStates.set(currentID, state);
  }
  const model = models.get(id);
  if (!model) return;
  currentID = id;
  editor.setModel(model);
  const state = viewStates.get(id);
  if (state) editor.restoreViewState(state);
}

const describe = (err) => String((err && err.message) || err || "unknown error");

let suspended = false;
let probeFrames = 0;
let probeHandle = null;

function startGatingProbe() {
  probeFrames = 0;
  if (probeHandle !== null) return;
  const tick = () => {
    probeFrames += 1;
    probeHandle = window.requestAnimationFrame(tick);
  };
  probeHandle = window.requestAnimationFrame(tick);
}

function stopGatingProbe() {
  if (probeHandle !== null) {
    window.cancelAnimationFrame(probeHandle);
    probeHandle = null;
  }
}

window.GrandLineCodePreview = bridge;

window.addEventListener("error", (event) => {
  post({ type: "error", message: String(event.message || "script error") });
});
window.addEventListener("unhandledrejection", (event) => {
  post({
    type: "error",
    message: String((event.reason && event.reason.message) || event.reason || "promise rejection"),
  });
});

post({ type: "ready" });
